'use strict';

/* ══════════════════════════════════════════════════════════
   LOCH — real 3D drag-a-black-hole game with rigid-body physics

   v2 of this minigame: v1 was a flat 2D canvas with abstract "tier"
   comparisons and no real geometry. This version is a real Three.js scene
   over a Cannon.js physics world — objects have actual size (a physics
   radius), get dropped into stacked piles at level start and settle under
   gravity, and the hole is a real trigger volume dragged around by a tall
   KINEMATIC collider (the "rim") that physically bumps into things —
   including piles, which is what makes disturbing one topple/crumble
   objects resting on top of it, using real physics rather than a scripted
   fracture system.

   Both Three.js and Cannon.js are vendored locally as classic global
   scripts (js/vendor/three.min.js defines window.THREE, js/vendor/
   cannon.min.js defines window.CANNON) — no bundler, no ES modules,
   matching every other script in this app. Three.js is pinned to r160.0.0,
   the last release that still shipped a working non-module global build;
   Cannon.js is the original schteppe/cannon.js (not the ESM-first
   cannon-es fork), for the same "just works from a <script> tag" reason.

   SHARED PHYSICS CONSTANTS below (HL_BOARD_HALF, HL_SIZE_CLASSES,
   HL_RIM_HEIGHT, HL_FLOOR_EPS) plus hlGenerateLevel/HL_LEVELS are the single
   source of truth for both this live game AND scripts/generate-hole-
   levels.js's offline drop-and-settle level generator (required from Node
   via the module.exports guard at the bottom, exactly like js/mosaik.js is
   required by scripts/verify-mosaik-levels.js) — the swallow rule must
   match exactly between generation-time verification and live play, or a
   level the generator proved solvable could turn out not to be.

   SIZING RULE: every object has an integer size class (index into
   HL_SIZE_CLASSES, the class's value being its real OBJECT physics radius).
   The hole can only swallow an object whose class <= the hole's own current
   class index — this eligibility check is INDEX-based, not a continuous
   "radius * growth margin" formula, deliberately, after an earlier
   continuous-growth attempt got stuck permanently unable to progress past
   the smallest class. Growing to the next class is a THRESHOLD
   (hlGrowthThreshold), not instant on the first eligible bite — eating any
   eligible object counts toward it, escalating per class — so there's a
   real "how far to the next size" meter to show (the hl-growth-bar UI,
   driven by hlRenderGrowthBar). The hole's own visual/physical radius
   (hlHoleRadii/hlHoleRadius) is a SEPARATE, far steeper curve than
   HL_SIZE_CLASSES — seeing the hole actually grow dramatically shouldn't
   depend on the object-size range staying small for solvability reasons.

   CAMERA follows the hole (recentered every frame) through a big sprawling
   world (HL_BOARD_HALF) rather than showing one small fixed board — driving
   toward the edge of the current view pans further into the world, and the
   orthographic frustum size (hlCamFrustum) eases wider as the hole grows,
   so a bigger hole visibly sees more of the world. Objects aren't scattered
   randomly either: scripts/generate-hole-levels.js places each level's
   piles on the "on" cells of a simple icon silhouette (circle/heart/house/
   etc.), GROUPED into uniform-size bands — a concentric-ring circle (same
   size per ring, growing outward), a flat triangle/house/tree in uniform
   rows — plus a dedicated vertical "stack" site type (several columns of
   one size piled to the top) — so a pile reads as a recognizable shape
   with real size structure, not just a silhouette scattered with random
   sizes. See that script's header for the full stencil/band system.

   All objects use a BOX physics collider regardless of their visual mesh
   shape (box/sphere/cylinder/cone/torus/icosahedron, chosen for variety) —
   a slightly-off collider for a non-box mesh is a standard, deliberate
   simplification in casual physics games. An earlier version used sphere
   colliders (cheaper/more stable collision in general), but measured
   directly: spheres barely stack at all — a sphere balanced on another is
   only in equilibrium if perfectly centered, so with any real drop jitter
   they just roll apart into a flat spread. Boxes (flat faces resting on
   flat faces) are what actually deliver "stuff on top of each other."
   scripts/generate-hole-levels.js's header has the rest of that story,
   including why the size-class range each level draws from is capped well
   below HL_SIZE_CLASSES' full spread — box piles with too wide a size
   mismatch can bury a small object under a big one in a way that's genuinely
   hard to guarantee reachable, not just a tuning inconvenience.
══════════════════════════════════════════════════════════ */

const HL_BOARD_HALF = 40; // a big, sprawling world — driving to the edge of the CAMERA view pans further into it, not the edge of a small fixed arena
const HL_SIZE_CLASSES = [0.14, 0.20, 0.28, 0.40, 0.55, 0.75, 1.00]; // OBJECT sizes (eatability rule) — generator caps actual usage at idx<=3, see its header
const HL_RIM_HEIGHT = 1.6;
const HL_FLOOR_EPS = 0.15;

// The HOLE's own visual/physical radius per class index — deliberately a
// separate, far steeper curve than HL_SIZE_CLASSES (which only governs
// what fits and stays capped low for solvability, see the generator's
// header). Without this decoupling the hole barely grows at all (its
// radius would be stuck following the same capped 0.14→0.40 object-size
// range); this curve is what makes growth actually *look* dramatic.
// Classes 0-3 stay close to a modest (~1.3x) margin over the biggest
// object actually eatable at that class (HL_SIZE_CLASSES[0..3] = 0.14,
// 0.20, 0.28, 0.40) — the hole's visual size needs to track what it can
// really eat there, or the "does this physically fit" comparison the whole
// mechanic is built on stops making sense (an earlier, far steeper curve
// made the hole look able to swallow everything nearby well before it
// actually could). Classes 4-6 are never reached by any object (generation
// caps objects at class 3) — only by the growth-threshold meter continuing
// past a level's real content — so they're free to ramp up dramatically
// for a "you're huge now" payoff without breaking that visual logic.
const HL_HOLE_RADII = [0.18, 0.26, 0.36, 0.52, 1.0, 2.0, 3.6];
function hlHoleRadius(classIdx) { return HL_HOLE_RADII[classIdx]; }

// How many eligible objects (class <= current) must be eaten before the
// hole grows to the next class — an escalating threshold rather than an
// instant grow-on-first-bite, so there's real "how far to the next size"
// progress to show (see hl-growth-bar in the live game section/index.html).
function hlGrowthThreshold(classIdx) { return 2 + classIdx; }

// Visual-only variety — geometry/color pairs objects are rendered as, keyed
// off a deterministic hash of (levelIndex, objectIndex) so the same object
// always renders the same way across a session, without needing to persist
// a shape choice in the save file.
const HL_SHAPES = ['box', 'sphere', 'cylinder', 'cone', 'torus', 'icosahedron'];
const HL_COLORS = [0xe8735a, 0x5aa8e8, 0x6fd88a, 0xe8d95a, 0xb06fe8, 0xe86fb0, 0x5adfd0, 0xe8a45a, 0x8a9be0];
function hlShapeFor(levelIndex, objectIndex) {
  const h = Math.imul(levelIndex + 1, 2654435761) ^ Math.imul(objectIndex + 1, 0x9e3779b9);
  const u = (h >>> 0);
  return { shape: HL_SHAPES[u % HL_SHAPES.length], color: HL_COLORS[(u >>> 8) % HL_COLORS.length] };
}

